#!/usr/bin/env node
// Web Scraper MCP relay — a zero-dependency MCP server (Streamable HTTP transport) that forwards
// Claude's tool calls to the Web Scraper extension running in the user's Chrome.
//
//   Claude ──POST /mcp/<token>──▶ relay ◀──GET /bridge/<token>/next── extension (long-poll)
//                                       ◀──POST /bridge/<token>/result──
//
// The <token> is a secret generated by the extension (Settings → Claude connector). Anyone who
// knows it can drive that browser's scraper, so treat the MCP URL like a password.
//
//   PORT=8787 node server/mcp-relay.mjs

import http from 'node:http';
import crypto from 'node:crypto';
import { TOOLS, INSTRUCTIONS } from './tools.mjs';

const PORT = Number(process.env.PORT || 8787);
const HOST = process.env.HOST || '0.0.0.0';
const CALL_TIMEOUT_MS = Number(process.env.CALL_TIMEOUT_MS || 240000);
const POLL_WAIT_MS = 25000;
const CONNECT_GRACE_MS = 8000; // how long a tool call waits for an offline extension to show up
const SUPPORTED_VERSIONS = ['2025-11-25', '2025-06-18', '2025-03-26', '2024-11-05'];
const VERSION = '0.3.0';
const TOKEN_RE = /^[A-Za-z0-9_-]{24,128}$/;

// ---------- per-token state ----------
const browsers = new Map(); // token -> { queue: [], waiters: [], pending: Map(id -> {resolve, timer}), lastSeen }

function browser(token) {
  let b = browsers.get(token);
  if (!b) {
    b = { queue: [], waiters: [], pending: new Map(), lastSeen: 0, info: {} };
    browsers.set(token, b);
  }
  return b;
}
const online = (b) => Date.now() - b.lastSeen < POLL_WAIT_MS + 10000;

function dispatch(token, tool, args) {
  const b = browser(token);
  const id = crypto.randomUUID();
  return new Promise((resolve) => {
    const timer = setTimeout(() => {
      b.pending.delete(id);
      b.queue = b.queue.filter((c) => c.id !== id);
      resolve({ isError: true, content: [{ type: 'text', text: online(b)
        ? `The extension did not finish "${tool}" within ${Math.round(CALL_TIMEOUT_MS / 1000)}s. Try a smaller job (fewer pages/URLs).`
        : 'The Web Scraper extension is not connected. Ask the user to open Chrome, open the Web Scraper side panel → Settings → Claude connector, and make sure it says "Connected".' }] });
    }, online(b) ? CALL_TIMEOUT_MS : CONNECT_GRACE_MS);
    b.pending.set(id, { resolve, timer, tool });
    const cmd = { id, tool, args };
    const waiter = b.waiters.shift();
    if (waiter) waiter(cmd); else b.queue.push(cmd);
  });
}

// ---------- HTTP helpers ----------
const CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-methods': 'GET, POST, DELETE, OPTIONS',
  'access-control-allow-headers': 'content-type, mcp-session-id, mcp-protocol-version, authorization, last-event-id',
  'access-control-expose-headers': 'mcp-session-id',
};

function send(res, status, body, headers = {}) {
  const isJson = body !== undefined && typeof body !== 'string';
  res.writeHead(status, { ...CORS, ...(isJson ? { 'content-type': 'application/json' } : body !== undefined ? { 'content-type': 'text/html; charset=utf-8' } : {}), ...headers });
  res.end(isJson ? JSON.stringify(body) : body);
}

async function readJson(req, limit = 20 * 1024 * 1024) {
  const chunks = [];
  let size = 0;
  for await (const c of req) {
    size += c.length;
    if (size > limit) throw new Error('Request too large');
    chunks.push(c);
  }
  const raw = Buffer.concat(chunks).toString('utf8');
  return raw ? JSON.parse(raw) : null;
}

// ---------- MCP (JSON-RPC over Streamable HTTP, JSON responses) ----------
async function handleRpc(token, msg) {
  const { id, method, params } = msg || {};
  const reply = (result) => ({ jsonrpc: '2.0', id, result });
  const fail = (code, message) => ({ jsonrpc: '2.0', id: id ?? null, error: { code, message } });
  if (!msg || msg.jsonrpc !== '2.0' || typeof method !== 'string') return fail(-32600, 'Invalid Request');
  if (id === undefined || id === null) return null; // notification: nothing to send back

  switch (method) {
    case 'initialize': {
      const requested = params?.protocolVersion;
      return reply({
        protocolVersion: SUPPORTED_VERSIONS.includes(requested) ? requested : SUPPORTED_VERSIONS[0],
        capabilities: { tools: { listChanged: false } },
        serverInfo: { name: 'web-scraper', title: 'Web Scraper (Chrome)', version: VERSION },
        instructions: INSTRUCTIONS,
      });
    }
    case 'ping':
      return reply({});
    case 'tools/list':
      return reply({ tools: TOOLS });
    case 'tools/call': {
      const name = params?.name;
      if (!TOOLS.some((t) => t.name === name)) return fail(-32602, `Unknown tool: ${name}`);
      const result = await dispatch(token, name, params?.arguments || {});
      return reply(result);
    }
    case 'resources/list':
      return reply({ resources: [] });
    case 'prompts/list':
      return reply({ prompts: [] });
    default:
      return fail(-32601, `Method not found: ${method}`);
  }
}

async function handleMcp(req, res, token) {
  if (req.method === 'GET') return send(res, 405, { error: 'This server does not offer an SSE stream; use POST.' }, { allow: 'POST, DELETE' });
  if (req.method === 'DELETE') return send(res, 200, {});
  if (req.method !== 'POST') return send(res, 405, { error: 'Method not allowed' });
  let body;
  try { body = await readJson(req); } catch { return send(res, 400, { jsonrpc: '2.0', id: null, error: { code: -32700, message: 'Parse error' } }); }
  const sessionHeader = { 'mcp-session-id': req.headers['mcp-session-id'] || crypto.randomUUID() };
  if (Array.isArray(body)) {
    const out = (await Promise.all(body.map((m) => handleRpc(token, m)))).filter(Boolean);
    return out.length ? send(res, 200, out, sessionHeader) : send(res, 202, undefined, sessionHeader);
  }
  const out = await handleRpc(token, body);
  return out ? send(res, 200, out, sessionHeader) : send(res, 202, undefined, sessionHeader);
}

// ---------- bridge for the extension ----------
function handleNext(req, res, token, url) {
  const b = browser(token);
  b.lastSeen = Date.now();
  b.info = { version: url.searchParams.get('v') || b.info.version, ua: req.headers['user-agent'] || '' };
  const cmd = b.queue.shift();
  if (cmd) return send(res, 200, cmd);
  let done = false;
  const finish = (c) => {
    if (done) return;
    done = true;
    clearTimeout(timer);
    b.lastSeen = Date.now();
    if (c) send(res, 200, c); else send(res, 204);
  };
  const waiter = (c) => finish(c);
  const timer = setTimeout(() => { b.waiters = b.waiters.filter((w) => w !== waiter); finish(null); }, POLL_WAIT_MS);
  req.on('close', () => {
    if (done) return;
    b.waiters = b.waiters.filter((w) => w !== waiter);
    done = true;
    clearTimeout(timer);
  });
  b.waiters.push(waiter);
}

async function handleResult(req, res, token) {
  const b = browser(token);
  b.lastSeen = Date.now();
  let body;
  try { body = await readJson(req); } catch { return send(res, 400, { error: 'bad json' }); }
  const p = b.pending.get(body?.id);
  if (!p) return send(res, 404, { error: 'unknown or expired command' });
  clearTimeout(p.timer);
  b.pending.delete(body.id);
  const content = Array.isArray(body.content) ? body.content : [{ type: 'text', text: String(body.error || 'No result') }];
  p.resolve({ content, isError: !!body.isError });
  return send(res, 200, { ok: true });
}

const STATUS_PAGE = `<!doctype html><meta charset="utf-8"><title>Web Scraper MCP relay</title>
<style>body{font:15px/1.5 system-ui,sans-serif;max-width:640px;margin:40px auto;padding:0 16px;color:#1c1c28}code{background:#f1f1f7;padding:2px 5px;border-radius:4px}</style>
<h1>Web Scraper MCP relay</h1><p>This server connects Claude to the <b>Web Scraper</b> Chrome extension.</p>
<ol><li>In the extension: Settings → <b>Claude connector</b> → enter this server's address and turn it on.</li>
<li>Copy the <b>MCP link</b> it shows (<code>https://this-server/mcp/&lt;secret&gt;</code>).</li>
<li>In Claude: Settings → Connectors → <b>Add custom connector</b> → paste the link.</li></ol><p>Status: running ✓ (v${VERSION})</p>`;

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    if (req.method === 'OPTIONS') return send(res, 204);
    const parts = url.pathname.split('/').filter(Boolean);
    if (!parts.length) return send(res, 200, STATUS_PAGE);
    if (parts[0] === 'health') return send(res, 200, { ok: true, version: VERSION, browsers: [...browsers.values()].filter(online).length });

    const token = parts[1];
    if ((parts[0] === 'mcp' || parts[0] === 'bridge') && !TOKEN_RE.test(token || '')) return send(res, 404, { error: 'Unknown or invalid token' });
    if (parts[0] === 'mcp' && parts.length === 2) return await handleMcp(req, res, token);
    if (parts[0] === 'bridge' && parts[2] === 'next' && req.method === 'GET') return handleNext(req, res, token, url);
    if (parts[0] === 'bridge' && parts[2] === 'result' && req.method === 'POST') return await handleResult(req, res, token);
    if (parts[0] === 'bridge' && parts[2] === 'status') {
      const b = browser(token);
      b.lastSeen = Date.now();
      return send(res, 200, { online: true, version: VERSION });
    }
    return send(res, 404, { error: 'Not found' });
  } catch (e) {
    console.error(e);
    if (!res.headersSent) send(res, 500, { error: String(e.message || e) });
  }
});
server.requestTimeout = 0; // long-polls and long tool calls
server.headersTimeout = 60000;
server.keepAliveTimeout = 65000;

// Forget idle browsers so memory stays bounded.
setInterval(() => {
  for (const [token, b] of browsers) if (!online(b) && !b.pending.size && !b.queue.length) browsers.delete(token);
}, 60000).unref();

server.listen(PORT, HOST, () => console.log(`Web Scraper MCP relay listening on http://${HOST}:${PORT}`));
export default server;
